import{_ as e,o,c as d,a3 as a}from"./chunks/framework.BTQ4eCVb.js";const h=JSON.parse('{"title":"Workspace upload policy + Task media — Production Readiness","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Workspace upload policy + Task media — Production Readiness | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/workspace-upload-policy-task-media-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Workspace upload policy + Task media — Production Readiness | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/workspace-upload-policy-task-media-production-readiness"}]]},"headers":[],"relativePath":"deployment/workspace-upload-policy-task-media-production-readiness.md","filePath":"deployment/workspace-upload-policy-task-media-production-readiness.md","lastUpdated":1789262965000}'),r={name:"deployment/workspace-upload-policy-task-media-production-readiness.md"};function s(n,t,i,c,l,g){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="workspace-upload-policy-task-media-—-production-readiness" tabindex="-1">Workspace upload policy + Task media — Production Readiness <a class="header-anchor" href="#workspace-upload-policy-task-media-—-production-readiness" aria-label="Permalink to &quot;Workspace upload policy + Task media — Production Readiness&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-09-09</td></tr><tr><td><strong>Status</strong></td><td><strong>Go</strong> — engineering complete (incl. authz/isolation Pest + mid-batch store rollback); Ops migrate + staging smoke before production traffic</td></tr><tr><td><strong>Scope</strong></td><td>Tenant <code>storage.upload_policy</code> (types + per-category max sizes) · shared enforcement on content uploads · Task + task-note multi-file attachments · SPA Upload limits + <code>useUploadPolicy</code></td></tr><tr><td><strong>Catalog</strong></td><td><strong>storage → 1.1.0</strong> · <strong>tasks → 1.4.0</strong></td></tr><tr><td><strong>Companion</strong></td><td><a href="./storage-production-readiness">Storage production readiness</a> · <a href="./storage">Storage ops</a> · <a href="/developer-guide/storage">Developer storage</a> · <a href="/user-guide/tasks">Tasks user guide</a></td></tr></tbody></table><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>This delivery adds a <strong>workspace-wide upload policy</strong> (Settings → Storage → Upload limits) and <strong>ClickUp-style task media</strong> (record + note attachments on the uploads disk with quota accounting).</p><ul><li>Setting key <code>storage.upload_policy</code> with platform caps in <code>config/storage.php</code></li><li><code>WorkspaceUploadPolicy</code> + <code>ValidatesWorkspaceUploads</code> on Chat, Expenses, Help Desk, Documents, Feedback, Knowledge Base, Lead imports, WhatsApp, and Tasks</li><li>Tables <code>task_attachments</code> / <code>task_note_attachments</code>; auth’d download/delete; bytes in <code>WorkspaceStorageService::usedBytes</code></li><li>SPA: Upload limits UI (<code>storage.manage</code> + <code>settings.update</code>); <code>useUploadPolicy</code> accept + client checks across content upload surfaces</li><li>Batch quota: task multi-file attach asserts <strong>sum of all files</strong> against remaining allowance before any store</li><li>Mid-batch store failure rolls back written objects + DB rows before rethrowing</li><li>Settings <code>updateMany</code> resolves the admin catalog <strong>outside</strong> the write transaction (avoids PHP 30s timeouts)</li><li>One-session Playwright human flow (<code>npm run test:e2e:upload-policy</code>); Pest policy + task attachment suites (incl. <code>storage.manage</code> 403 + cross-tenant download/delete)</li></ul><p><strong>Go / No-Go:</strong> <strong>Go</strong> — ship after companion CI green; Ops migrate catalog bumps and complete staging smoke. Mobile task media remains <strong>deferred</strong> (accepted for this release).</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Migrations <code>040000</code> attachments + <code>040100</code> catalog bumps</td><td><strong>Pass</strong></td></tr><tr><td>Catalog DB <code>storage</code> <strong>1.1.0</strong> / <code>tasks</code> <strong>1.4.0</strong></td><td><strong>Pass</strong></td></tr><tr><td><code>CatalogSeeder</code> versions aligned</td><td><strong>Pass</strong></td></tr><tr><td>Policy write gated (<code>settings.update</code> + <code>storage.manage</code>)</td><td><strong>Pass</strong> (+ Pest 403 without <code>storage.manage</code>)</td></tr><tr><td>Cross-surface BE validation</td><td><strong>Pass</strong> (FormRequests)</td></tr><tr><td>Task attach policies + private disk (<code>public: false</code>)</td><td><strong>Pass</strong> (+ Pest cross-tenant 404)</td></tr><tr><td>Batch quota assert (multi-file)</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Mid-batch store rollback</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>FE Upload limits + <code>useUploadPolicy</code> surfaces</td><td><strong>Pass</strong></td></tr><tr><td>Pest <code>WorkspaceUploadPolicyTest</code> + <code>TaskAttachmentTest</code></td><td><strong>Pass</strong> (local 2026-09-09, 14 tests)</td></tr><tr><td>Playwright <code>test:e2e:upload-policy</code></td><td><strong>Pass</strong> (local 2026-09-09, ~4.5m)</td></tr><tr><td>Docs user/API/changelog + this readiness page</td><td><strong>Pass</strong></td></tr><tr><td>Mobile task attachments / upload-policy UI</td><td><strong>Deferred</strong> (Product-accepted)</td></tr><tr><td>Soft concurrent over-quota (cross-request race)</td><td>Accepted residual (same as Storage v1)</td></tr><tr><td>Content malware scan</td><td>Accepted residual (extension allowlist)</td></tr></tbody></table><hr><h2 id="catalog-version-path" tabindex="-1">Catalog version path <a class="header-anchor" href="#catalog-version-path" aria-label="Permalink to &quot;Catalog version path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Migration</th><th>Effect</th></tr></thead><tbody><tr><td><code>2026_09_09_040000_create_task_attachments_tables</code></td><td><code>task_attachments</code> + <code>task_note_attachments</code></td></tr><tr><td><code>2026_09_09_040100_bump_tasks_and_storage_module_versions_for_upload_policy</code></td><td><strong>storage → 1.1.0</strong>, <strong>tasks → 1.4.0</strong></td></tr></tbody></table><p>Production: <strong>migrate only</strong>. Do <strong>not</strong> <code>db:seed</code> on upgrade. Fresh local/CI seed uses <code>CatalogSeeder</code> versions aligned to these bumps.</p><hr><h2 id="deploy-order" tabindex="-1">Deploy order <a class="header-anchor" href="#deploy-order" aria-label="Permalink to &quot;Deploy order&quot;">​</a></h2><ol><li>Deploy <strong>Backend</strong></li><li><code>php artisan migrate --force</code> (through <code>040100</code>)</li><li>Confirm central catalog <code>storage.version</code> = <strong>1.1.0</strong>, <code>tasks.version</code> = <strong>1.4.0</strong></li><li>Confirm <code>FILESYSTEM_UPLOADS_DISK</code> / object storage (existing Storage runbook) — task objects under <code>tenants/{uuid}/tasks/</code></li><li>Deploy <strong>SPA</strong></li><li>Deploy <strong>Docs</strong></li><li>Staging smoke below</li></ol><p>Suggested merge order: <strong>Backend → Frontend → Docs</strong>.</p><p>No new env vars or queue workers. Uploads remain synchronous.</p><hr><h2 id="pre-flight-checklist" tabindex="-1">Pre-flight checklist <a class="header-anchor" href="#pre-flight-checklist" aria-label="Permalink to &quot;Pre-flight checklist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Check</th><th>Owner</th><th>Pass?</th></tr></thead><tbody><tr><td>1</td><td>Migrations through <code>040100</code> applied</td><td>Ops</td><td>☐</td></tr><tr><td>2</td><td>Catalog <code>storage</code> = <strong>1.1.0</strong>, <code>tasks</code> = <strong>1.4.0</strong></td><td>Ops</td><td>☐</td></tr><tr><td>3</td><td>Settings → Storage shows <strong>Upload limits</strong>; save requires <code>storage.manage</code></td><td>QA</td><td>☐</td></tr><tr><td>4</td><td>Task create with 2 images → view shows both; download works; delete removes object</td><td>QA</td><td>☐</td></tr><tr><td>5</td><td>Comment with note attachment; download works</td><td>QA</td><td>☐</td></tr><tr><td>6</td><td>Rejected type (e.g. <code>.exe</code>) blocked client-side on Tasks / Documents / Expenses</td><td>QA</td><td>☐</td></tr><tr><td>7</td><td>Documents Office-style types still upload when enabled in policy</td><td>QA</td><td>☐</td></tr><tr><td>8</td><td>Storage quota still blocks oversize / over-allowance uploads</td><td>QA</td><td>☐</td></tr><tr><td>9</td><td>Pest Storage + Task attachment suites green in CI</td><td>Eng</td><td>☐</td></tr><tr><td>10</td><td>Playwright <code>npm run test:e2e:upload-policy</code> green</td><td>QA</td><td>☐</td></tr></tbody></table><hr><h2 id="staging-smoke-human" tabindex="-1">Staging smoke (human) <a class="header-anchor" href="#staging-smoke-human" aria-label="Permalink to &quot;Staging smoke (human)&quot;">​</a></h2><ol><li>Marketplace → Storage installed (or already entitled)</li><li>Settings → Storage → set max image <strong>0.1 MB</strong>, uncheck <strong>GIF</strong>, <strong>Save upload limits</strong></li><li>Tasks → New (full page) → empty title validation → attach <code>.exe</code> (rejected) → attach small PNG + TXT → <strong>Create &amp; View</strong> → files listed</li><li>Add comment with TXT attachment</li><li>Documents → reject <code>.exe</code> → upload <code>.txt</code> / Office type allowed by policy</li><li>Expenses / Help Desk create → reject <code>.exe</code>, accept allowed image/text</li><li>Restore Upload limits to defaults (or leave documented test values)</li></ol><hr><h2 id="audit-findings-→-remediation" tabindex="-1">Audit findings → remediation <a class="header-anchor" href="#audit-findings-→-remediation" aria-label="Permalink to &quot;Audit findings → remediation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Finding</th><th>Action</th></tr></thead><tbody><tr><td>H1</td><td>High</td><td>Multi-file <code>assertCanStore</code> per file could overshoot quota</td><td><strong>Fixed</strong> — batch byte sum before store (<code>TaskService::attachFiles</code> / <code>attachNoteFiles</code>) + Pest</td></tr><tr><td>H2</td><td>High</td><td>Settings <code>PUT</code> double <code>forAdminApi</code> / in-transaction catalog walk → PHP 30s</td><td><strong>Fixed</strong> — single resolve outside write transaction</td></tr><tr><td>M1</td><td>Medium</td><td><code>CatalogSeeder</code> missing bump versions</td><td><strong>Fixed</strong> — <code>tasks</code> <strong>1.4.0</strong>, <code>storage</code> <strong>1.1.0</strong></td></tr><tr><td>M2</td><td>Medium</td><td>Developer tasks guide still cited <strong>1.2.0</strong></td><td><strong>Fixed</strong> in this ship</td></tr><tr><td>M3</td><td>Medium</td><td>Thin Pest on <code>storage.manage</code> 403 / cross-tenant download</td><td><strong>Fixed</strong> — Pest 403 + cross-tenant download/delete 404 (task + note)</td></tr><tr><td>M4</td><td>Medium</td><td>Mid-batch attach could leave orphan objects</td><td><strong>Fixed</strong> — <code>storeAttachmentBatch</code> deletes paths/rows on failure + Pest</td></tr><tr><td>L1</td><td>Low</td><td>Lead import <code>accept</code> fixed to csv/txt/xlsx</td><td>Intentional; size/type still via policy</td></tr><tr><td>I1</td><td>Info</td><td>Mobile deferred</td><td>Accepted for this release — release notes</td></tr><tr><td>I2</td><td>Info</td><td>Extension allowlist (no content virus scan)</td><td>Accepted SaaS posture</td></tr><tr><td>I3</td><td>Info</td><td>Soft cross-request quota race</td><td>Same as Storage v1</td></tr></tbody></table><hr><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Action</th></tr></thead><tbody><tr><td>Frontend</td><td>Redeploy previous SPA (Upload limits UI + task media disappear; older clients ignore new fields)</td></tr><tr><td>Backend code</td><td>Redeploy previous release; catalog version may remain <strong>1.1.0</strong> / <strong>1.4.0</strong> (display-only)</td></tr><tr><td>Schema</td><td>Forward-fix preferred — <strong>do not</strong> <code>migrate:rollback</code> in production; attachment tables are additive</td></tr><tr><td>Policy setting</td><td>Rows in <code>tenant_settings</code> for <code>storage.upload_policy</code> can remain; unused without new code</td></tr></tbody></table><hr><h2 id="sign-off" tabindex="-1">Sign-off <a class="header-anchor" href="#sign-off" aria-label="Permalink to &quot;Sign-off&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Name</th><th>Date</th><th>Decision</th></tr></thead><tbody><tr><td>Engineering</td><td></td><td>2026-09-09</td><td>☑ <strong>Go</strong> (CI green + Ops smoke still required before traffic)</td></tr><tr><td>Ops</td><td></td><td></td><td>☐ Migrate + catalog confirm + staging smoke</td></tr><tr><td>Product</td><td></td><td></td><td>☑ Mobile deferred accepted for this release</td></tr></tbody></table><p><strong>Current decision (2026-09-09):</strong> <strong>Go</strong> — engineering residuals from the audit are closed; merge after companion CI green; Ops migrate through <code>040100</code> and complete staging smoke before production traffic. Mobile task media remains out of scope.</p><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./storage-production-readiness">Storage production readiness</a> (packs / grandfather / gateway)</li><li><a href="./storage">Storage production guide</a></li><li><a href="/developer-guide/storage">Developer Storage</a></li><li><a href="/developer-guide/tasks">Developer Tasks</a></li><li><a href="/developer-guide/object-storage">Object storage</a></li><li><a href="/api/tenant-v1-storage">Tenant Storage API</a></li><li><a href="/api/tenant-v1-tasks">Tenant Tasks API</a></li><li><a href="/changelog/">Changelog</a></li></ul>',36)])])}const u=e(r,[["render",s]]);export{h as __pageData,u as default};
